/**
 * ─────────────────────────────────────────────────────────────────────────────
 *  LEDGERLY DATABASE SCHEMA
 *
 *  This file is the single source of truth for the database structure.
 *  `pnpm db:generate` compares it with the previous migration snapshot and
 *  writes a new SQL migration in /migrations. Never edit the database by hand.
 *
 *  Conventions (see docs/stage-03-database-design.md):
 *   - Tables: plural snake_case. Columns: snake_case.
 *   - Primary keys: UUID v7 (time-ordered), generated by the application.
 *   - Every table has created_at/updated_at (timestamptz, maintained by a trigger).
 *   - Money: bigint in minor units (cents), column name ends in `_minor`.
 *   - Every tenant-owned table carries household_id, and cross-table references
 *     use COMPOSITE foreign keys that include household_id, so the database itself
 *     makes it impossible to link data from two different households.
 * ─────────────────────────────────────────────────────────────────────────────
 */
import { sql } from "drizzle-orm";
import {
  bigint,
  boolean,
  char,
  check,
  date,
  foreignKey,
  jsonb,
  index,
  integer,
  pgEnum,
  pgTable,
  primaryKey,
  smallint,
  text,
  timestamp,
  unique,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";
import { v7 as uuidv7 } from "uuid";

// ─── Reusable column builders ────────────────────────────────────────────────

/** UUID v7 primary key: unique everywhere, unguessable, and sorted by creation time. */
const id = () =>
  uuid("id")
    .primaryKey()
    .$defaultFn(() => uuidv7());

const createdAt = () => timestamp("created_at", { withTimezone: true }).notNull().defaultNow();
const updatedAt = () => timestamp("updated_at", { withTimezone: true }).notNull().defaultNow();

/** ISO 4217 currency code, e.g. "USD". Validated by a CHECK constraint on each table. */
const currency = (name: string) => char(name, { length: 3 });
const currencyCheck = (table: string, column: { name: string }) =>
  check(`${table}_${column.name}_iso4217`, sql`${sql.identifier(column.name)} ~ '^[A-Z]{3}$'`);

/** Money in minor units. JS numbers are exact up to 2^53 (≈ $90 trillion in cents). */
const money = (name: string) => bigint(name, { mode: "number" });

// ─── Enums ───────────────────────────────────────────────────────────────────

export const householdRole = pgEnum("household_role", ["owner", "editor", "viewer"]);

export const accountType = pgEnum("account_type", [
  "checking",
  "savings",
  "credit_card",
  "cash",
  "investment",
  "loan",
]);

export const categoryKind = pgEnum("category_kind", ["income", "expense"]);

export const jobStatus = pgEnum("job_status", ["queued", "running", "succeeded", "failed"]);

export const importStatus = pgEnum("import_status", [
  "uploaded", // file stored and previewed; waiting for the user to confirm the column mapping
  "queued", // confirmed; a background job will pick it up
  "processing",
  "completed",
  "failed",
  "reverted", // the user undid it: its transactions were deleted
]);

export const recurringCadence = pgEnum("recurring_cadence", ["weekly", "twice_monthly", "monthly"]);

// ─── Users ───────────────────────────────────────────────────────────────────

export const users = pgTable(
  "users",
  {
    id: id(),
    email: text("email").notNull(),
    displayName: text("display_name").notNull(),
    /**
     * Argon2id hash in PHC format ("$argon2id$v=19$m=19456,t=2,p=1$salt$hash").
     * The algorithm, parameters and salt travel WITH the hash, so we can raise the
     * cost later and re-hash on next login. Nullable: future single-sign-on users
     * may never have a password.
     */
    passwordHash: text("password_hash"),
    /** TOTP secret, ENCRYPTED with AES-256-GCM (never stored in plain text). */
    totpSecretEncrypted: text("totp_secret_encrypted"),
    /** Non-null = two-factor authentication is on. */
    totpEnabledAt: timestamp("totp_enabled_at", { withTimezone: true }),
    /** Last accepted 30-second TOTP time step: stops the same code being replayed. */
    totpLastUsedStep: bigint("totp_last_used_step", { mode: "number" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    // Case-insensitive uniqueness: "Alex@Mail.com" and "alex@mail.com" are the same person.
    uniqueIndex("users_email_lower_key").on(sql`lower(${t.email})`),
    check("users_email_shape", sql`${t.email} ~ '^[^@\\s]+@[^@\\s]+$'`),
    check("users_display_name_length", sql`char_length(${t.displayName}) between 1 and 100`),
  ],
);

// ─── Sessions ────────────────────────────────────────────────────────────────

/**
 * A signed-in browser/device. The cookie holds a random 256-bit token; the
 * database stores only its SHA-256 hash. A stolen database backup therefore
 * contains no usable session tokens — the same principle as hashing passwords.
 */
export const sessions = pgTable(
  "sessions",
  {
    /** Public id, used to list and revoke sessions. NOT the secret token. */
    id: id(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    tokenHash: text("token_hash").notNull(),
    /** Password was correct, but the second factor hasn't been verified yet. */
    mfaPending: boolean("mfa_pending").notNull().default(false),
    ipAddress: text("ip_address"),
    userAgent: text("user_agent"),
    createdAt: createdAt(),
    lastSeenAt: timestamp("last_seen_at", { withTimezone: true }).notNull().defaultNow(),
    /** Absolute expiry: even an active session must sign in again eventually. */
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
  },
  (t) => [
    uniqueIndex("sessions_token_hash_key").on(t.tokenHash),
    index("sessions_user_id_idx").on(t.userId),
    // For the cleanup job that deletes expired sessions (Stage 10).
    index("sessions_expires_at_idx").on(t.expiresAt),
  ],
);

/** One-time backup codes for when the authenticator app is lost. Stored hashed. */
export const recoveryCodes = pgTable(
  "recovery_codes",
  {
    id: id(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    codeHash: text("code_hash").notNull(),
    usedAt: timestamp("used_at", { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [unique("recovery_codes_user_id_code_hash_key").on(t.userId, t.codeHash)],
);

// ─── Households (our "tenants") ──────────────────────────────────────────────

export const households = pgTable(
  "households",
  {
    id: id(),
    name: text("name").notNull(),
    baseCurrency: currency("base_currency").notNull().default("USD"),
    /**
     * IANA time zone ("America/Los_Angeles"). Background jobs have no browser to
     * ask what "today" is, so the household remembers its own calendar.
     * Validated in the API with Intl (the database has no list of zones to check against).
     */
    timeZone: text("time_zone").notNull().default("UTC"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    currencyCheck("households", t.baseCurrency),
    check("households_name_length", sql`char_length(${t.name}) between 1 and 100`),
  ],
);

/** Many-to-many: a user can belong to several households, a household has several users. */
export const householdMembers = pgTable(
  "household_members",
  {
    householdId: uuid("household_id")
      .notNull()
      .references(() => households.id, { onDelete: "cascade" }),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    role: householdRole("role").notNull().default("viewer"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    primaryKey({ name: "household_members_pkey", columns: [t.householdId, t.userId] }),
    // The PK index starts with household_id; this one answers "which households am I in?"
    index("household_members_user_id_idx").on(t.userId),
  ],
);

// ─── Accounts (bank accounts, cards, cash…) ──────────────────────────────────

export const accounts = pgTable(
  "accounts",
  {
    id: id(),
    householdId: uuid("household_id")
      .notNull()
      .references(() => households.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    type: accountType("type").notNull(),
    currency: currency("currency").notNull(),
    openingBalanceMinor: money("opening_balance_minor").notNull().default(0),
    archivedAt: timestamp("archived_at", { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    currencyCheck("accounts", t.currency),
    check("accounts_name_length", sql`char_length(${t.name}) between 1 and 100`),
    // Two accounts in one household can't share a name. This index also serves
    // "list accounts of household X" because it starts with household_id.
    unique("accounts_household_id_name_key").on(t.householdId, t.name),
    // Target for composite foreign keys from transactions (see below).
    unique("accounts_id_household_id_key").on(t.id, t.householdId),
  ],
);

// ─── Categories (two levels: "Food" → "Groceries") ──────────────────────────

export const categories = pgTable(
  "categories",
  {
    id: id(),
    householdId: uuid("household_id")
      .notNull()
      .references(() => households.id, { onDelete: "cascade" }),
    parentId: uuid("parent_id"),
    name: text("name").notNull(),
    kind: categoryKind("kind").notNull(),
    icon: text("icon"),
    sortOrder: integer("sort_order").notNull().default(0),
    archivedAt: timestamp("archived_at", { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    unique("categories_id_household_id_key").on(t.id, t.householdId),
    // A parent must live in the SAME household (composite self-reference).
    foreignKey({
      name: "categories_parent_fkey",
      columns: [t.parentId, t.householdId],
      foreignColumns: [t.id, t.householdId],
    }),
    // No duplicate names among siblings. NULLS NOT DISTINCT makes two top-level
    // categories (parent_id IS NULL) with the same name count as duplicates too.
    unique("categories_household_parent_name_key")
      .on(t.householdId, t.parentId, t.name)
      .nullsNotDistinct(),
    check("categories_not_own_parent", sql`${t.parentId} <> ${t.id}`),
    check("categories_name_length", sql`char_length(${t.name}) between 1 and 50`),
  ],
);

// ─── Imports (bank CSV files) ────────────────────────────────────────────────

/**
 * One uploaded CSV file and the state of its import. The file's text is kept
 * only until the import finishes — bank statements are sensitive, and data we
 * no longer need is data that can't leak ("data minimisation").
 */
export const imports = pgTable(
  "imports",
  {
    id: id(),
    householdId: uuid("household_id")
      .notNull()
      .references(() => households.id, { onDelete: "cascade" }),
    accountId: uuid("account_id").notNull(),
    createdBy: uuid("created_by").references(() => users.id, { onDelete: "set null" }),
    fileName: text("file_name").notNull(),
    fileSize: integer("file_size").notNull(),
    fileText: text("file_text"),
    status: importStatus("status").notNull().default("uploaded"),
    /** How the CSV's columns map to our fields (set when the user confirms). */
    mapping: jsonb("mapping"),
    totalRows: integer("total_rows").notNull().default(0),
    processedRows: integer("processed_rows").notNull().default(0),
    importedCount: integer("imported_count").notNull().default(0),
    duplicateCount: integer("duplicate_count").notNull().default(0),
    errorCount: integer("error_count").notNull().default(0),
    /** The first few row-level problems, e.g. [{ row: 12, message: "Unreadable date" }]. */
    errors: jsonb("errors").$type<Array<{ row: number; message: string }>>().notNull().default([]),
    failureReason: text("failure_reason"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    completedAt: timestamp("completed_at", { withTimezone: true }),
  },
  (t) => [
    foreignKey({
      name: "imports_account_fkey",
      columns: [t.accountId, t.householdId],
      foreignColumns: [accounts.id, accounts.householdId],
    }).onDelete("cascade"),
    unique("imports_id_household_id_key").on(t.id, t.householdId),
    index("imports_household_created_idx").on(t.householdId, t.createdAt),
    check("imports_file_name_length", sql`char_length(${t.fileName}) between 1 and 255`),
    check(
      "imports_counts_not_negative",
      sql`${t.totalRows} >= 0 and ${t.processedRows} >= 0 and ${t.importedCount} >= 0 and ${t.duplicateCount} >= 0 and ${t.errorCount} >= 0`,
    ),
  ],
);

// ─── Recurring rules ─────────────────────────────────────────────────────────

/**
 * "Every month on the 1st, record Rent: −$1,650 from Checking." A scheduled
 * background job creates the transactions when they fall due.
 */
export const recurringRules = pgTable(
  "recurring_rules",
  {
    id: id(),
    householdId: uuid("household_id")
      .notNull()
      .references(() => households.id, { onDelete: "cascade" }),
    accountId: uuid("account_id").notNull(),
    categoryId: uuid("category_id"),
    description: text("description").notNull(),
    amountMinor: money("amount_minor").notNull(),
    cadence: recurringCadence("cadence").notNull(),
    /** Day of month for monthly rules, the FIRST day for twice-monthly ones. */
    anchorDay: smallint("anchor_day"),
    /** The second day of month for twice-monthly rules (e.g. 1st and 15th). */
    secondDay: smallint("second_day"),
    /** The next date a transaction is due. The scheduler advances it. */
    nextDate: date("next_date", { mode: "string" }).notNull(),
    active: boolean("active").notNull().default(true),
    /** The detected series this rule was created from (see detectRecurring), if any. */
    seriesKey: text("series_key"),
    createdBy: uuid("created_by").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    foreignKey({
      name: "recurring_rules_account_fkey",
      columns: [t.accountId, t.householdId],
      foreignColumns: [accounts.id, accounts.householdId],
    }).onDelete("cascade"),
    foreignKey({
      name: "recurring_rules_category_fkey",
      columns: [t.categoryId, t.householdId],
      foreignColumns: [categories.id, categories.householdId],
    }),
    // The scheduler's question, across ALL households: "which active rules are due?"
    index("recurring_rules_due_idx")
      .on(t.nextDate)
      .where(sql`${t.active}`),
    uniqueIndex("recurring_rules_household_series_key")
      .on(t.householdId, t.seriesKey)
      .where(sql`${t.seriesKey} is not null`),
    check("recurring_rules_amount_not_zero", sql`${t.amountMinor} <> 0`),
    check(
      "recurring_rules_description_length",
      sql`char_length(${t.description}) between 1 and 200`,
    ),
    check(
      "recurring_rules_days",
      sql`(${t.cadence} = 'weekly' and ${t.anchorDay} is null and ${t.secondDay} is null)
       or (${t.cadence} = 'monthly' and ${t.anchorDay} between 1 and 31 and ${t.secondDay} is null)
       or (${t.cadence} = 'twice_monthly' and ${t.anchorDay} between 1 and 31 and ${t.secondDay} between 1 and 31 and ${t.anchorDay} < ${t.secondDay})`,
    ),
  ],
);

// ─── Transactions ────────────────────────────────────────────────────────────

export const transactions = pgTable(
  "transactions",
  {
    id: id(),
    householdId: uuid("household_id")
      .notNull()
      .references(() => households.id, { onDelete: "cascade" }),
    accountId: uuid("account_id").notNull(),
    categoryId: uuid("category_id"),
    /** Signed, in the account's currency: positive = money in, negative = money out. */
    amountMinor: money("amount_minor").notNull(),
    /** The calendar day it happened — a DATE, not a timestamp (see the doc, §6.4). */
    occurredOn: date("occurred_on", { mode: "string" }).notNull(),
    description: text("description").notNull(),
    notes: text("notes"),
    /**
     * Moving money between your own accounts (paying the credit card, saving) is
     * stored as TWO rows — money out of one account, money in to the other — that
     * share a transfer_id. Transfers are neither income nor spending, so reports
     * exclude them.
     */
    transferId: uuid("transfer_id"),
    /** Set on rows created by a CSV import (so the import can be undone). */
    importId: uuid("import_id"),
    /**
     * A hash of (date, amount, description, occurrence) from the bank file. A
     * UNIQUE index per account makes re-importing an overlapping file skip rows
     * it has already seen — duplicates are prevented by the database itself.
     */
    importFingerprint: text("import_fingerprint"),
    /** Set on rows created by a recurring rule. */
    recurringRuleId: uuid("recurring_rule_id").references(() => recurringRules.id, {
      onDelete: "set null",
    }),
    createdBy: uuid("created_by").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    // The account and category MUST belong to the same household as the transaction.
    foreignKey({
      name: "transactions_account_fkey",
      columns: [t.accountId, t.householdId],
      foreignColumns: [accounts.id, accounts.householdId],
    }),
    foreignKey({
      name: "transactions_category_fkey",
      columns: [t.categoryId, t.householdId],
      foreignColumns: [categories.id, categories.householdId],
    }),
    check("transactions_amount_not_zero", sql`${t.amountMinor} <> 0`),
    check(
      "transactions_transfer_has_no_category",
      sql`${t.transferId} is null or ${t.categoryId} is null`,
    ),
    check("transactions_description_length", sql`char_length(${t.description}) between 1 and 200`),
    // The main screen: "this household's transactions, newest first".
    // Declared ascending on purpose: a B-tree can be read BACKWARDS, and a backward
    // scan of (ASC NULLS LAST) is exactly `ORDER BY occurred_on DESC, id DESC`
    // (whose default is NULLS FIRST). Declaring it `DESC NULLS LAST` would NOT match
    // and Postgres would have to sort — see the doc §7.3 for the measured difference.
    // The same index powers fast keyset pagination.
    index("transactions_household_occurred_idx").on(t.householdId, t.occurredOn, t.id),
    // Account register and balance calculations.
    index("transactions_account_occurred_idx").on(t.accountId, t.occurredOn),
    // Find the other half of a transfer.
    index("transactions_transfer_idx")
      .on(t.transferId)
      .where(sql`${t.transferId} is not null`),
    // Category reports. Partial index: uncategorised rows aren't indexed at all.
    index("transactions_category_idx")
      .on(t.categoryId)
      .where(sql`${t.categoryId} is not null`),
    foreignKey({
      name: "transactions_import_fkey",
      columns: [t.importId, t.householdId],
      foreignColumns: [imports.id, imports.householdId],
    }),
    index("transactions_import_idx")
      .on(t.importId)
      .where(sql`${t.importId} is not null`),
    uniqueIndex("transactions_account_import_fingerprint_key")
      .on(t.accountId, t.importFingerprint)
      .where(sql`${t.importFingerprint} is not null`),
    // A rule creates AT MOST one transaction per due date — even if the job runs twice.
    uniqueIndex("transactions_recurring_occurrence_key")
      .on(t.recurringRuleId, t.occurredOn)
      .where(sql`${t.recurringRuleId} is not null`),
  ],
);

// ─── Budgets ─────────────────────────────────────────────────────────────────

/**
 * A monthly spending limit for one expense category (spending in its
 * subcategories counts too). The AMOUNT lives in `budget_amounts`, effective-
 * dated: raising your groceries budget in March must not rewrite January's
 * history — or every past month's "over/under" would silently change.
 */
export const budgets = pgTable(
  "budgets",
  {
    id: id(),
    householdId: uuid("household_id")
      .notNull()
      .references(() => households.id, { onDelete: "cascade" }),
    categoryId: uuid("category_id").notNull(),
    /** First month the budget applies to (always the 1st of a month). */
    startMonth: date("start_month", { mode: "string" }).notNull(),
    /** Carry what's left (or overspent) into the next month. */
    rollover: boolean("rollover").notNull().default(false),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    // The category must belong to the same household (Stage 3's composite-FK pattern).
    foreignKey({
      name: "budgets_category_fkey",
      columns: [t.categoryId, t.householdId],
      foreignColumns: [categories.id, categories.householdId],
    }).onDelete("cascade"),
    unique("budgets_household_category_key").on(t.householdId, t.categoryId),
    check("budgets_start_month_is_first", sql`extract(day from ${t.startMonth}) = 1`),
  ],
);

/** Effective-dated amounts: the amount for month M is the latest row with effective_month <= M. */
export const budgetAmounts = pgTable(
  "budget_amounts",
  {
    budgetId: uuid("budget_id")
      .notNull()
      .references(() => budgets.id, { onDelete: "cascade" }),
    effectiveMonth: date("effective_month", { mode: "string" }).notNull(),
    amountMinor: money("amount_minor").notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    primaryKey({ name: "budget_amounts_pkey", columns: [t.budgetId, t.effectiveMonth] }),
    check("budget_amounts_positive", sql`${t.amountMinor} > 0`),
    check("budget_amounts_month_is_first", sql`extract(day from ${t.effectiveMonth}) = 1`),
  ],
);

// ─── Savings goals ───────────────────────────────────────────────────────────

/**
 * A target balance for one account ("Emergency fund: $25,000 in High-Yield
 * Savings"). Progress is the account's REAL balance, so it updates itself as
 * money moves — no manual "add contribution" bookkeeping to forget.
 */
export const goals = pgTable(
  "goals",
  {
    id: id(),
    householdId: uuid("household_id")
      .notNull()
      .references(() => households.id, { onDelete: "cascade" }),
    accountId: uuid("account_id").notNull(),
    name: text("name").notNull(),
    targetMinor: money("target_minor").notNull(),
    /** Optional deadline; enables "on track / behind" and "save $X per month". */
    targetDate: date("target_date", { mode: "string" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    foreignKey({
      name: "goals_account_fkey",
      columns: [t.accountId, t.householdId],
      foreignColumns: [accounts.id, accounts.householdId],
    }).onDelete("cascade"),
    check("goals_target_positive", sql`${t.targetMinor} > 0`),
    check("goals_name_length", sql`char_length(${t.name}) between 1 and 60`),
  ],
);

// ─── Idempotency keys (safe retries for POST requests) ───────────────────────

/**
 * When a client sends `Idempotency-Key: <uuid>` with a POST, we store the response
 * here. If the same request is retried (flaky mobile network, user double-clicks),
 * we replay the stored response instead of creating a duplicate transaction.
 */
export const idempotencyKeys = pgTable(
  "idempotency_keys",
  {
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    key: text("key").notNull(),
    /** Hash of method + path + body: the same key with a DIFFERENT request is an error. */
    requestHash: text("request_hash").notNull(),
    responseStatus: integer("response_status").notNull(),
    responseBody: jsonb("response_body").notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    primaryKey({ name: "idempotency_keys_pkey", columns: [t.userId, t.key] }),
    // Old keys are purged after 24 h (by a background job in Stage 10).
    index("idempotency_keys_created_at_idx").on(t.createdAt),
    check("idempotency_keys_key_length", sql`char_length(${t.key}) between 1 and 255`),
  ],
);

// ─── Personal preferences ────────────────────────────────────────────────────

/**
 * Each member's own dashboard arrangement for each household (widget ids in
 * display order). Personal, so even viewers may change it. Stored on the server
 * so the layout follows you from laptop to phone.
 */
export const dashboardLayouts = pgTable(
  "dashboard_layouts",
  {
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    householdId: uuid("household_id")
      .notNull()
      .references(() => households.id, { onDelete: "cascade" }),
    widgets: jsonb("widgets").$type<string[]>().notNull(),
    updatedAt: updatedAt(),
  },
  (t) => [primaryKey({ name: "dashboard_layouts_pkey", columns: [t.userId, t.householdId] })],
);

// ─── Background jobs ─────────────────────────────────────────────────────────

/**
 * A job queue, in Postgres. Workers claim jobs with `FOR UPDATE SKIP LOCKED`
 * (see apps/api/src/jobs). Living in the same database as the data means a job
 * can be enqueued in the SAME transaction as the change that needs it: either
 * both happen or neither does — no "saved the import but lost its job".
 */
export const jobs = pgTable(
  "jobs",
  {
    // SQL default too, so the database trigger in migration 0008 can insert jobs.
    id: uuid("id")
      .primaryKey()
      .defaultRandom()
      .$defaultFn(() => uuidv7()),
    name: text("name").notNull(),
    payload: jsonb("payload").notNull().default({}),
    status: jobStatus("status").notNull().default("queued"),
    /** Not before this moment: used for delays, retries with backoff and debouncing. */
    runAt: timestamp("run_at", { withTimezone: true }).notNull().defaultNow(),
    attempts: integer("attempts").notNull().default(0),
    /** null = use the job type's default (see JobDefinition.maxAttempts). */
    maxAttempts: integer("max_attempts"),
    /** A running job's lease. If the worker dies, the lease expires and another worker retries it. */
    lockedUntil: timestamp("locked_until", { withTimezone: true }),
    lockedBy: text("locked_by"),
    lastError: text("last_error"),
    /** At most ONE queued job per key: later enqueues with the same key are dropped (debouncing). */
    singletonKey: text("singleton_key"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    finishedAt: timestamp("finished_at", { withTimezone: true }),
  },
  (t) => [
    index("jobs_ready_idx")
      .on(t.runAt)
      .where(sql`${t.status} = 'queued'`),
    index("jobs_running_lease_idx")
      .on(t.lockedUntil)
      .where(sql`${t.status} = 'running'`),
    index("jobs_finished_idx")
      .on(t.finishedAt)
      .where(sql`${t.status} in ('succeeded', 'failed')`),
    uniqueIndex("jobs_singleton_key")
      .on(t.singletonKey)
      .where(sql`${t.status} = 'queued'`),
    check(
      "jobs_attempts",
      sql`${t.attempts} >= 0 and (${t.maxAttempts} is null or ${t.maxAttempts} between 1 and 25)`,
    ),
  ],
);

/**
 * Recurring schedules ("every 15 minutes, run recurring.run-due"). Several
 * workers may be running; the one that atomically moves next_run_at forward
 * wins the tick, so each tick enqueues exactly one job — no leader election needed.
 */
export const jobSchedules = pgTable("job_schedules", {
  name: text("name").primaryKey(),
  intervalSeconds: integer("interval_seconds").notNull(),
  nextRunAt: timestamp("next_run_at", { withTimezone: true }).notNull(),
  lastRunAt: timestamp("last_run_at", { withTimezone: true }),
});

// ─── Notifications ───────────────────────────────────────────────────────────

/**
 * In-app notifications, one row per recipient. `dedupe_key` + a unique index
 * make "notify Alex that Groceries went over in November" happen EXACTLY once,
 * however many times the evaluation job runs.
 */
export const notifications = pgTable(
  "notifications",
  {
    id: id(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    householdId: uuid("household_id")
      .notNull()
      .references(() => households.id, { onDelete: "cascade" }),
    kind: text("kind").notNull(),
    title: text("title").notNull(),
    body: text("body").notNull(),
    /** In-app path to open, e.g. /app/<household>/budgets */
    link: text("link"),
    dedupeKey: text("dedupe_key").notNull(),
    readAt: timestamp("read_at", { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("notifications_user_dedupe_key").on(t.userId, t.dedupeKey),
    index("notifications_user_created_idx").on(t.userId, t.createdAt),
    index("notifications_user_unread_idx")
      .on(t.userId)
      .where(sql`${t.readAt} is null`),
  ],
);

// ─── Inferred TypeScript types ───────────────────────────────────────────────
// `$inferSelect` = a row read from the DB. `$inferInsert` = what you pass to insert
// (columns with defaults become optional).

export type User = typeof users.$inferSelect;
export type Session = typeof sessions.$inferSelect;
export type NewUser = typeof users.$inferInsert;
export type Household = typeof households.$inferSelect;
export type NewHousehold = typeof households.$inferInsert;
export type HouseholdMember = typeof householdMembers.$inferSelect;
export type Account = typeof accounts.$inferSelect;
export type NewAccount = typeof accounts.$inferInsert;
export type Category = typeof categories.$inferSelect;
export type NewCategory = typeof categories.$inferInsert;
export type Transaction = typeof transactions.$inferSelect;
export type Budget = typeof budgets.$inferSelect;
export type BudgetAmount = typeof budgetAmounts.$inferSelect;
export type Goal = typeof goals.$inferSelect;
export type NewTransaction = typeof transactions.$inferInsert;
export type Job = typeof jobs.$inferSelect;
export type Import = typeof imports.$inferSelect;
export type RecurringRule = typeof recurringRules.$inferSelect;
export type Notification = typeof notifications.$inferSelect;
